import { lazy } from 'react';
import { HeartPulse as IcHeartPulse, LineChart as IcLineChart, RefreshCw as IcRefreshCw, SlidersHorizontal as IcSlidersHorizontal, TrendingUp as IcTrendingUp } from 'lucide-react';
import { TabHub } from '@/components/pulse-ui';

/**
 * Inventory Planning — hub page for the Inventory menu.
 *
 * Generated by the 2026-09-16 information-architecture pass, which collapsed
 * 4 sidebar rows into this one destination. Each page below keeps its
 * NAV_ITEMS entry marked `inHub: 'InventoryPlanning'`, so getSectionForPage() still
 * resolves it and every role gate behaves exactly as it did when each was its
 * own row. TabHub re-checks each tab with canRoleOpenPage() before drawing it.
 */
const DemandPlanning = lazy(() => import('./DemandPlanning'));
const InventoryPlanningParameters = lazy(() => import('./InventoryPlanningParameters'));
const InventoryHealth = lazy(() => import('./InventoryHealth'));
const KanbanLoops = lazy(() => import('./KanbanLoops'));

export const TABS = [
  { id: 'demand', label: 'Demand Planning', icon: IcTrendingUp, page: 'DemandPlanning', Component: DemandPlanning },
  { id: 'parameters', label: 'Planning Parameters', icon: IcSlidersHorizontal, page: 'InventoryPlanningParameters', Component: InventoryPlanningParameters },
  { id: 'health', label: 'Inventory Health', icon: IcHeartPulse, page: 'InventoryHealth', Component: InventoryHealth },
  { id: 'kanban', label: 'Kanban Loops', icon: IcRefreshCw, page: 'KanbanLoops', Component: KanbanLoops },
];

export default function InventoryPlanning({ setPage }) {
  return (
    <TabHub
      icon={IcLineChart}
      eyebrow="Inventory"
      title="Inventory Planning"
      subtitle="Demand forecast, EOQ and safety-stock parameters, health and pull loops"
      tabs={TABS}
      setPage={setPage}
    />
  );
}
